W='http://schemas.openxmlformats.org/wordprocessingml/2006/main';NS={'w':W,'a':'http://schemas.openxmlformats.org/drawingml/2006/main','r':'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
def doc_reader(name):
 f=OUT/'output'/name;parts=[]
 with ZipFile(f) as z:
  root=E.fromstring(z.read('word/document.xml'));rels=E.fromstring(z.read('word/_rels/document.xml.rels'));rel={x.get('Id'):x.get('Target') for x in rels}
  def para(p):
   txt=''.join(p.xpath('.//w:t/text()',namespaces=NS));ims=[]
   for blip in p.findall('.//a:blip',NS):
    target=rel.get(blip.get('{'+NS['r']+'}embed'),'')
    if target.startswith('media/'):
     local='assets/documents/'+Path(target).name;dest=OUT/local;dest.parent.mkdir(exist_ok=True)
     dest.write_bytes(z.read('word/'+target));ims.append('<img src="'+local+'" alt="Recorded classroom demonstration state">')
   if not txt.strip():return ''.join(ims) or '<p class="blank" aria-hidden="true"></p>'
   style=p.find('w:pPr/w:pStyle',NS);kind=style.get('{'+W+'}val') if style is not None else ''
   tag='h2' if kind in ('Title','Heading1','Heading2') else 'p'
   return f'<{tag}>'+h(txt)+f'</{tag}>'+''.join(ims)
  for el in root.find('w:body',NS):
   if E.QName(el).localname=='p':parts.append(para(el))
   elif E.QName(el).localname=='tbl':
    rows=[]
    for ri,tr in enumerate(el.findall('w:tr',NS)):
     cells=[]
     for tc in tr.findall('w:tc',NS):
      span=tc.find('w:tcPr/w:gridSpan',NS);attr=' colspan="'+span.get('{'+W+'}val')+'"' if span is not None else ''
      cells.append('<td'+attr+'>'+''.join(para(p) for p in tc.findall('w:p',NS))+'</td>')
     rows.append('<tr>'+''.join(cells)+'</tr>')
    parts.append('<table>'+''.join(rows)+'</table>')
 return '<section class="doc">'+''.join(parts)+'</section>'
