timer_js='''<script>
const duration=420000;let remaining=duration,running=false,deadline=0,round=0;
const time=document.querySelector('#time'),phase=document.querySelector('#phase'),toggle=document.querySelector('#toggle'),status=document.querySelector('#status'),select=document.querySelector('#round'),next=document.querySelector('#next');
function sync(){if(running){remaining=Math.max(0,deadline-Date.now());if(remaining===0){running=false;status.textContent=round===2?'Round 3 complete. Begin four-minute self review, then three-minute revision.':'Round complete. Reset and rotate, then select the next round.';}}const sec=Math.ceil(remaining/1000),elapsed=(duration-remaining)/1000;time.textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');phase.textContent=remaining===0?'Round complete':elapsed<45?'State the task, input and success':elapsed<225?'Attempt the task; record evidence and help':elapsed<315?'Compare expectation with the observed result':elapsed<375?'Choose a strength and one revision or uncertainty':'Write the retest, reset and rotate';toggle.textContent=running?'Pause':remaining===0?'Round complete':remaining===duration?'Start round':'Resume';toggle.disabled=remaining===0;next.disabled=round===2;select.disabled=running;}
function reset(){running=false;remaining=duration;status.textContent='Ready. The timer stops at the end; it does not advance automatically.';sync();}
toggle.addEventListener('click',()=>{if(running){sync();running=false;status.textContent='Paused.';}else{deadline=Date.now()+remaining;running=true;status.textContent='Round '+(round+1)+' running.';}sync();});
document.querySelector('#reset').addEventListener('click',reset);select.addEventListener('change',()=>{round=Number(select.value);reset();});next.addEventListener('click',()=>{if(round<2){round++;select.value=String(round);reset();}});setInterval(sync,100);sync();
</script>'''
